		),
		'bolo-cocada-molhadinho' => array(
			'en_slug'             => 'moist-coconut-cake',
			'en_title'            => 'Moist Coconut Cake (Cocada Molhadinho)',
			'en_excerpt'          => 'A budget-friendly coconut cake that bakes up soft and creamy inside, finished with a sweet coconut and condensed-milk drizzle.',
			'en_meta_description' => 'Chef Sonia Campos\' moist coconut cake: a simple blender recipe with a coconut and condensed-milk drizzle to finish.',
			'en_content'          => '<h2></h2>
</p>
</p>
<h2><strong>         </strong></h2>
<h2><strong>Chef Sonia Campos</strong> <u>@grannymadeireland</u></h2>
<p><strong>​</strong></p>
<p><strong>Ingredients:</strong></p>
<p><strong>3 eggs</strong></p>
<p><strong>A few drops of vanilla (optional)</strong></p>
<p><strong>1 tin of condensed milk (395g)A pinch of salt</strong></p>
<p><strong>150g desiccated or flaked coconut</strong></p>
<p><strong>1 small bottle of coconut milk (200ml)</strong></p>
<p><strong>1 cup (120g) cornflour</strong></p>
<p><strong>1 tablespoon (16g) baking powder</strong></p>
<p><strong>​</strong></p>
<p><strong>Method:</strong></p>
<p><strong>Preheat the oven to 180°C and grease a medium tin with butter and cornflour or flour.</strong></p>
<p><strong>In a blender, add the eggs, the condensed milk, the coconut milk, the vanilla (if using) and the pinch of salt. Blend for about 2 minutes until smooth.</strong></p>
<p><strong>Add the desiccated coconut and the cornflour. Blend again until well combined.</strong></p>
<p><strong>Add the baking powder last and stir gently with a spoon, or blend briefly just to combine.</strong></p>
<p><strong>Pour the batter into the prepared tin. Bake for about 35 to 45 minutes, or until nicely golden on top.Let it cool a little before cutting. It stays slightly creamy inside — that is the perfect texture of this moist coconut cake!</strong></p>
<p><strong>Tip from Chef Sonia Campos: To make it even moister and tastier, mix:3 tablespoons of coconut milk1 tablespoon of condensed milk.</strong></p>
</p>
<p><strong>Drizzle this over the cake while it is still warm and finish with desiccated coconut on top.</strong></p>
</p>
<p><strong>It is simply irresistible!</strong></p>
',
